static z_t7164_t z_t7164_copy(const z_t7164_t* _this) {
    z_t7164_t _out = {0};
    if (!_this || _this->length == 0) return _out;
    _out.length = _this->length;
    _out.capacity = _this->length;
    _out.data = (z_t7159_t*)z_xcalloc(_this->length, sizeof(z_t7159_t));
    memcpy(_out.data, _this->data, (size_t)_this->length * sizeof(z_t7159_t));
    return _out;
}

