static const z_t6517_t _zag3115 = { { .data = "win_sep", .size = 7 }, { .length = 1, .data = _zag3114 }, { .length = 0, .data = NULL }, { .data = "static int z_win_sep(char c) {\n    return c == '\\\\' || c == '/';\n}", .size = 66 } };
