static const z_t6517_t _zag3316 = { { .data = "span64", .size = 6 }, { .length = 1, .data = _zag3314 }, { .length = 2, .data = _zag3315 }, { .data = "/* z_span64 -- how many bits lie from the highest set bit of v down to its\n   lowest, both counted: the significand an integer needs to convert to a\n   float exactly. 0 for 0. */\nstatic inline int z_span64(uint64_t v) { return v == 0 ? 0 : 64 - z_clz64(v) - z_ctz64(v); }", .size = 271 } };
